mapper.update:
UPDATE sales_order
customer_id = #{customerId}, warehouse_id = #{warehouseId}, total_amount = #{totalAmount}, status = #{status}, order_date = #{orderDate}, remark = #{remark}, updated_at = CURRENT_TIMESTAMP
WHERE id = #{id}

mapper.select:
SELECT so.order_no, c.customer_name, p.sku_code, p.product_name, p.spec, soi.quantity, soi.price, soi.amount, so.order_date, u.real_name as salesman_name, CASE so.status WHEN 0 THEN '草稿' WHEN 1 THEN '已出库' WHEN 2 THEN '已取消' END as status_desc FROM sales_order so LEFT JOIN customer c ON so.customer_id = c.id LEFT JOIN sales_order_item soi ON so.id = soi.order_id LEFT JOIN product p ON soi.product_id = p.id LEFT JOIN sys_user u ON so.salesman_id = u.id WHERE so.status = 1
AND so.order_date >= #{startDate}
AND so.order_date <= #{endDate}
AND so.customer_id = #{customerId}
AND so.warehouse_id = #{warehouseId}
ORDER BY so.order_date DESC, so.order_no DESC

SELECT so.id, so.order_no, so.customer_id, c.customer_name, so.warehouse_id, so.total_amount, so.status, so.salesman_id, so.order_date, so.remark, so.created_at FROM sales_order so LEFT JOIN customer c ON so.customer_id = c.id WHERE 1=1
AND so.order_no LIKE CONCAT('%', #{orderNo}, '%')
ORDER BY so.created_at DESC LIMIT #{offset}, #{pageSize}
